-- GASP dataset customer (snapshot; Customer). snapshot rows on month starts, month ends and the period bounds shifted back by one, three, six and twelve months
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.customer (
  acquisition_date DATE,
  activation_date DATE,
  composite_score DECIMAL(18, 6),
  criteria_met BOOLEAN,
  csm_id VARCHAR(1000),
  customer_id VARCHAR(1000),
  customer_status VARCHAR(1000),
  last_active_date DATE,
  onboarding_completion_date DATE,
  qbr_completed BOOLEAN,
  qbr_due BOOLEAN,
  segment VARCHAR(1000),
  snapshot_date DATE,
  upgrade_eligible BOOLEAN
);
